import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class WatchProtocolDecoderTest {

    private static final Protocol MOCK_PROTOCOL = new Protocol();

    @Test
    public void WatchProtocolDecoderProtocolConstructorTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(MOCK_PROTOCOL);
        assertNotNull(decoder);
        assertEquals(MOCK_PROTOCOL, decoder.getProtocol());
    }

    @Test
    public void getHasIndexTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(MOCK_PROTOCOL);
        assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(MOCK_PROTOCOL);
        assertNull(decoder.getManufacturer());
    }

    @Test
    public void decodeWithDataTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(MOCK_PROTOCOL);
        Channel mockChannel = Mockito.mock(Channel.class);
        Object expectedMsg = "Sample Message";
        SocketAddress mockAddress = Mockito.mock(SocketAddress.class);
        assertNotNull(decoder.decode(mockChannel, mockAddress, expectedMsg));
    }

    @Test
    public void decodeWithNullDataTest() {        
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(MOCK_PROTOCOL);
        Channel mockChannel = Mockito.mock(Channel.class);
        assertNull(decoder.decode(mockChannel, Mockito.mock(SocketAddress.class), null));
    }

    @Test(expected = Exception.class)
    public void decodeWithExceptionTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(MOCK_PROTOCOL);
        Channel mockChannel = Mockito.mock(Channel.class);
        SocketAddress mockAddress = Mockito.mock(SocketAddress.class);
        decoder.decode(mockChannel, mockAddress, new Object());
    }
}
